static bool watch=false;static unsigned allocations=0;
void*operator new(std::size_t n){if(watch)++allocations;if(void*p=std::malloc(n?n:1))return p;throw std::bad_alloc();}
void operator delete(void*p)noexcept{std::free(p);}void operator delete(void*p,std::size_t)noexcept{std::free(p);}
#define CHECK(x) do{if(!(x)){std::fprintf(stderr,"FAIL %d %s\n",__LINE__,#x);std::exit(1);}}while(false)
struct Synth{bs_synth*p=bs_create();explicit Synth(double rate=48000){CHECK(p&&bs_prepare(p,rate));}~Synth(){bs_destroy(p);}};
struct Audio{std::vector<float>l,r;explicit Audio(unsigned n):l(n),r(n){}};
static Audio render(bs_synth*s,unsigned n,unsigned block=127){Audio a(n);for(unsigned start=0;start<n;start+=block){watch=true;int result=bs_render(s,a.l.data()+start,a.r.data()+start,std::min(block,n-start),nullptr,0);watch=false;CHECK(result==0);}for(unsigned i=0;i<n;++i)CHECK(std::isfinite(a.l[i])&&std::isfinite(a.r[i])&&std::abs(a.l[i])<=1&&std::abs(a.r[i])<=1);return a;}
static void configure(bs_synth*s,unsigned count,float detune,float spread){bs_voicing_config c{1,count,detune,spread};CHECK(bs_set_voicing(s,&c));}
static void sine(bs_synth*s){bs_set_parameter(s,BS_OSC1_WAVE,BS_SINE);bs_set_parameter(s,BS_OSC1_LEVEL,1);bs_set_parameter(s,BS_OSC2_LEVEL,0);bs_set_parameter(s,BS_FILTER_MIX,0);bs_set_parameter(s,BS_SUSTAIN_LEVEL,1);bs_set_parameter(s,BS_RELEASE,.05f);bs_reset(s);}
static double energy(const std::vector<float>&v){double sum=0;for(float x:v)sum+=double(x)*x;return sum;}
static double amplitude(const std::vector<float>&v,double frequency){double re=0,im=0;const unsigned begin=12000;for(unsigned i=begin;i<v.size();++i){double w=.5-.5*std::cos(6.283185307179586*(i-begin)/(v.size()-begin-1));double phase=6.283185307179586*frequency*i/48000;re+=v[i]*w*std::cos(phase);im+=v[i]*w*std::sin(phase);}return std::hypot(re,im)/(v.size()-begin);}
#define GUARD_CHECK(x) do{if(!(x)){std::printf("FAIL guard %d %s\n",__LINE__,#x);return 1;}}while(0)
void setup(bs_synth*s,unsigned wave){for(auto pair:std::vector<std::pair<unsigned,float>>{{BS_GAIN,.2f},{BS_OSC1_LEVEL,1},{BS_OSC2_LEVEL,0},{BS_OSC1_WAVE,float(wave)},{BS_FILTER_MIX,0},{BS_DRIVE_ENABLED,0},{BS_FULLNESS_ENABLED,0},{BS_DRIFT_CENTS,0},{BS_SETTLING_CENTS,0},{BS_VELOCITY_MOVEMENT,0},{BS_PITCH_DROP_ENABLED,0},{BS_ATTACK,.001f},{BS_SUSTAIN_LEVEL,1},{BS_RELEASE,.01f}})if(!bs_set_parameter(s,pair.first,pair.second))std::abort();}
unsigned worst(unsigned count,unsigned key){double low=2;unsigned result=1;for(unsigned seq=1;seq<=1000;++seq){std::array<double,BS_MAX_UNISON>a{},b{};blocks_detail::Unison::startPhases(seq,key,0,count,a,b);std::complex<double>z{};for(unsigned i=0;i<count;++i)z+=std::polar(1.,6.283185307179586*a[i]);if(std::abs(z)<low){low=std::abs(z);result=seq;}}return result;}
struct Stats{double energy=0,peak=0,jump=0,dc=0;};
Stats audio(bs_synth*s,unsigned frames){std::vector<float>l(frames),r(frames);watch=true;int status=bs_render(s,l.data(),r.data(),frames,nullptr,0);watch=false;if(status)std::abort();Stats out;for(unsigned i=0;i<frames;++i){if(!std::isfinite(l[i])||!std::isfinite(r[i]))std::abort();if(i>=frames/2){out.energy+=(l[i]*l[i]+r[i]*r[i])/2;out.dc+=(l[i]+r[i])/2;}out.peak=std::max({out.peak,double(std::abs(l[i])),double(std::abs(r[i]))});if(i)out.jump=std::max({out.jump,double(std::abs(l[i]-l[i-1])),double(std::abs(r[i]-r[i-1]))});}out.energy/=frames/2;out.dc/=frames/2;return out;}
static int guardMatrix(){double low=10,high=0,peak=0,liveLow=10,livePeak=0;unsigned cases=0;for(unsigned count=2;count<=BS_MAX_UNISON;++count)for(unsigned wave=0;wave<5;++wave)for(unsigned key:{24u,48u,60u,72u})for(float spread:{0.f,1.f}){auto*s=bs_create();auto*b=bs_create();GUARD_CHECK(s&&b&&bs_prepare(s,48000)&&bs_prepare(b,48000));setup(s,wave);setup(b,wave);bs_voicing_config c{1,count,0,spread};GUARD_CHECK(bs_set_voicing(s,&c));bs_reset(s);bs_reset(b);unsigned seq=worst(count,key);for(unsigned i=1;i<seq;++i){bs_note_on(s,0,key,.8f);bs_panic(s);}bs_note_on(s,0,key,.8f);bs_note_on(b,0,key,.8f);auto a=audio(s,24000),base=audio(b,24000);double ratio=std::sqrt(a.energy/base.energy);low=std::min(low,ratio);high=std::max(high,ratio);peak=std::max(peak,a.peak);GUARD_CHECK(ratio>.3&&ratio<1.2&&a.peak<1&&bs_active_voices(s)==1);c.detune_cents=10;GUARD_CHECK(bs_set_voicing(s,&c));audio(s,24000);c.detune_cents=0;GUARD_CHECK(bs_set_voicing(s,&c));auto transition=audio(s,48000);ratio=std::sqrt(transition.energy/base.energy);liveLow=std::min(liveLow,ratio);livePeak=std::max(livePeak,transition.peak);GUARD_CHECK(ratio>.3&&ratio<1.2&&transition.peak<1&&transition.jump<.1&&std::abs(transition.dc)<.01&&bs_active_voices(s)==1);bs_note_off(s,0,key);audio(s,4800);GUARD_CHECK(bs_active_voices(s)==0);bs_destroy(s);bs_destroy(b);++cases;}std::printf("PASS %u D0/10-to0 cases wave0..4/count2..7/C1,C3,C4,C5/spread0,1; staticRMSratio %.8f..%.8f peak %.8f; liveMinRatio %.8f peak %.8f\n",cases,low,high,peak,liveLow,livePeak);return 0;}

